use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

fn run() -> Result<String, String> {
    let path = env::args()
        .nth(1)
        .ok_or_else(|| "missing journal.log path".to_string())?;
    let contents = fs::read_to_string(&path)
        .map_err(|error| format!("cannot read '{}': {}", path, error))?;
    let mut state: HashMap<String, String> = HashMap::new();
    let mut order: Vec<String> = Vec::new();

    for (line_number, raw_line) in contents.lines().enumerate() {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        if line.is_empty() {
            return Err(format!("malformed record on line {}", line_number + 1));
        }
        let parts: Vec<&str> = line.split('|').collect();
        if parts.len() != 3 || parts[1].is_empty() {
            return Err(format!("malformed record on line {}", line_number + 1));
        }
        let key = parts[1].to_string();
        match parts[0] {
            "put" => {
                if !state.contains_key(&key) {
                    order.push(key.clone());
                }
                state.insert(key, parts[2].to_string());
            }
            "delete" => {
                if !parts[2].is_empty() {
                    return Err(format!("malformed delete on line {}", line_number + 1));
                }
                state.remove(&key);
            }
            kind => {
                return Err(format!("unknown record kind '{}'", kind));
            }
        }
    }

    let mut output = String::new();
    for key in order {
        if let Some(value) = state.get(&key) {
            output.push_str(&key);
            output.push('=');
            output.push_str(value);
            output.push('\n');
        }
    }
    Ok(output)
}

fn main() {
    match run() {
        Ok(output) => print!("{}", output),
        Err(error) => {
            eprintln!("{}", error);
            process::exit(1);
        }
    }
}
